using System.Text.Json;
using DevFortress;
using Xunit;

namespace DevFortress.Sdk.Tests;

/// <summary>
/// Byte-for-byte against the shared cross-language vectors
/// (<c>contracts/ingest-signature-vectors.json</c>, repo root — generated by an independent
/// Python script, not by any SDK), the same fixture Go's <c>vectors_test.go</c>, Ruby's
/// <c>signing_vectors_test.rb</c> and Java's <c>SignerVectorsTest</c> run against.
/// <see cref="Signer.Verify"/> is checked against every vector; <see cref="Signer.Sign"/>
/// byte-for-byte reproduction is only checked for "valid"/"expired" vectors, since every
/// other vector's wire headers were deliberately tampered and so would never match a fresh
/// sign of the same sign_input.
/// </summary>
public class SignerVectorsTests
{
    private static readonly string VectorsPath = ContractsPath.For("ingest-signature-vectors.json");

    private static JsonElement LoadVectors()
    {
        string text = File.ReadAllText(VectorsPath);
        using var doc = JsonDocument.Parse(text);
        return doc.RootElement.GetProperty("vectors").Clone();
    }

    private static string? Str(JsonElement el, string prop) =>
        el.TryGetProperty(prop, out var v) && v.ValueKind != JsonValueKind.Null ? v.GetString() : null;

    private static Dictionary<string, string?> WireHeaders(JsonElement vector)
    {
        var headers = vector.GetProperty("headers");
        return new Dictionary<string, string?>
        {
            [Signer.NonceHeader] = Str(headers, "nonce"),
            [Signer.TimestampHeader] = Str(headers, "timestamp"),
            [Signer.PayloadHashHeader] = Str(headers, "payload_hash"),
            [Signer.SignatureHeader] = Str(headers, "signature"),
            [Signer.VersionHeader] = Str(headers, "version"),
        };
    }

    public static IEnumerable<object[]> VectorNames()
    {
        var vectors = LoadVectors();
        foreach (var vector in vectors.EnumerateArray())
        {
            yield return [vector.GetProperty("name").GetString()!];
        }
    }

    [Fact]
    public void ExpectsAtLeast26Vectors()
    {
        Assert.True(LoadVectors().GetArrayLength() >= 26);
    }

    [Theory]
    [MemberData(nameof(VectorNames))]
    public void EveryVerifierVectorGivesItsExpectedResult(string name)
    {
        var vector = LoadVectors().EnumerateArray().First(v => v.GetProperty("name").GetString() == name);

        long nowMs = vector.GetProperty("now_ms").GetInt64();
        var expected = Enum.Parse<Signer.VerifyResult>(ToPascalCase(vector.GetProperty("expected").GetString()!), ignoreCase: true);

        var actual = Signer.Verify(
            Str(vector, "verify_key")!, Str(vector, "method")!, Str(vector, "request_target")!,
            Str(vector, "body") ?? "", WireHeaders(vector), nowMs);

        Assert.True(expected == actual, $"verify() mismatch for vector {name}: expected {expected}, got {actual}");
    }

    [Theory]
    [MemberData(nameof(VectorNames))]
    public void SigningMatchesTheVectorsByteForByteWhenApplicable(string name)
    {
        var vector = LoadVectors().EnumerateArray().First(v => v.GetProperty("name").GetString() == name);

        string expected = vector.GetProperty("expected").GetString()!;
        if (!vector.TryGetProperty("sign_input", out var signIn) || (expected != "valid" && expected != "expired"))
        {
            return; // Not applicable to this vector — see type doc.
        }

        var signer = new Signer(Str(signIn, "api_key")!);
        var signed = signer.Sign(
            Str(signIn, "method")!, Str(signIn, "request_target")!, Str(signIn, "body") ?? "",
            Str(signIn, "timestamp"), Str(signIn, "nonce"));
        var want = WireHeaders(vector);

        Assert.Equal(want[Signer.PayloadHashHeader]!.ToLowerInvariant(), signed[Signer.PayloadHashHeader]);
        Assert.Equal(want[Signer.SignatureHeader]!.ToLowerInvariant(), signed[Signer.SignatureHeader]);
        Assert.Equal(want[Signer.NonceHeader], signed[Signer.NonceHeader]);
        Assert.Equal(want[Signer.TimestampHeader], signed[Signer.TimestampHeader]);
        Assert.Equal("2", signed[Signer.VersionHeader]);
    }

    [Fact]
    public void DeriveKeyIdIsFirst32HexCharsOfSha256()
    {
        string keyId = Signer.DeriveKeyId("vx_live_test_vector_key_do_not_use");
        Assert.Equal(32, keyId.Length);
        Assert.Matches("^[0-9a-f]{32}$", keyId);
    }

    [Fact]
    public void KeyIdDerivationVectorsMatch()
    {
        var root = JsonDocument.Parse(File.ReadAllText(VectorsPath)).RootElement;
        var vectors = root.GetProperty("key_id_derivation").GetProperty("vectors");
        int count = 0;
        foreach (var v in vectors.EnumerateArray())
        {
            Assert.Equal(Str(v, "key_id"), Signer.DeriveKeyId(Str(v, "api_key")!));
            count++;
        }
        Assert.True(count >= 3);
    }

    [Fact]
    public void RequestTargetFromUrlStripsSchemeAndHost()
    {
        Assert.Equal("/api/events/ingest", Signer.RequestTargetFromUrl("https://www.devfortress.net/api/events/ingest"));
        Assert.Equal("/a/b?x=1&y=2", Signer.RequestTargetFromUrl("https://host/a/b?x=1&y=2"));
        Assert.Equal("/", Signer.RequestTargetFromUrl("https://host"));
    }

    private static string ToPascalCase(string snake) =>
        string.Concat(snake.Split('_').Select(p => char.ToUpperInvariant(p[0]) + p[1..]));
}
